#!/usr/bin/env python3
"""Compare both irradiance outputs against a native wave64 control."""
import argparse
import json
import math
import os
from pathlib import Path
import shutil
import struct
import subprocess
import sys
from tempfile import TemporaryDirectory

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from build import Toolchain
from check_frosty_shaders import containers, decoder, decompress, global_archive
from project_tuxbox.host import Host
from project_tuxbox.inspect import digest
from project_tuxbox.shader_prep import compiler_tools

CASES = ("active", "width1", "width2", "width3", "partial", "quarter", "empty", "rejected")


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("mount", type=Path)
    p.add_argument("--prefix-amd", type=Path, required=True)
    p.add_argument("--prefix-nvidia", type=Path, required=True)
    p.add_argument("--proton", type=Path, required=True)
    p.add_argument("--amd-vulkan", type=Path)
    p.add_argument("--xshader", type=Path)
    p.add_argument("--output", type=Path, required=True)
    args = p.parse_args()
    compiler, dxc, dxv = compiler_tools()
    compiler = args.xshader.resolve() if args.xshader else compiler
    with TemporaryDirectory(dir=ROOT / "build") as temp:
        work = Path(temp)
        payload, entries = global_archive(args.mount)
        ((_, native, _),) = containers(decompress(payload, entries[485], decoder()))
        (work / "native.cso").write_bytes(native)
        portable = work / "portable.hlsl"
        subprocess.run([compiler, work / "native.cso", "--hlsl-out", portable], check=True)
        text = portable.read_text()
        begin, end = text.index("groupshared uint page_bits"), text.index("// Generated by")
        reference = text[:begin] + """
uint2 tb_page_ballot(uint tid, bool vote) { return WaveActiveBallot(vote).xy; }
uint tb_page_read(uint tid, uint value, uint lane) { return WaveReadLaneAt(value, lane & 63u); }
""" + text[end:]
        reference = reference.replace("[numthreads(8, 8, 1)]", "[WaveSize(64)]\n[numthreads(8, 8, 1)]", 1)
        (work / "reference.hlsl").write_text(reference)
        for name, profile in (("portable", "cs_6_0"), ("reference", "cs_6_6")):
            subprocess.run([dxc, "-T", profile, "-E", "main", "-O3", "-Fo", work / f"{name}.cso", work / f"{name}.hlsl"], check=True)
            subprocess.run([dxv, work / f"{name}.cso"], check=True, stdout=subprocess.DEVNULL)
        toolchain = Toolchain()
        obj = toolchain.compile(ROOT / "tools/reference/irradiance/guest.cpp", work, "/W4", "/WX", f"/I{ROOT / 'runtime/d3d12'}")
        exe = work / "probe.exe"
        toolchain.link(exe, obj, "d3d12.lib", "dxgi.lib", "kernel32.lib")
        saved = os.environ.copy()
        results, reference_outputs = {}, {}
        try:
            for name, adapter, prefix, shader in (("native_amd", "AMD", args.prefix_amd, "reference"),
                                                   ("portable_amd", "AMD", args.prefix_amd, "portable"),
                                                   ("portable_nvidia", "NVIDIA", args.prefix_nvidia, "portable")):
                os.environ["VKD3D_FILTER_DEVICE_NAME"] = adapter
                os.environ["DXVK_FILTER_DEVICE_NAME"] = adapter
                if adapter == "AMD" and args.amd_vulkan:
                    os.environ["VK_DRIVER_FILES"] = str(args.amd_vulkan)
                elif adapter == "NVIDIA":
                    os.environ.pop("VK_DRIVER_FILES", None)
                shutil.copyfile(work / f"{shader}.cso", work / "shader.cso")
                run = Host(None, args.proton, prefix).run(exe, [], timeout=60, capture=True)
                receipt = (work / "result.txt").read_text(errors="replace")
                if run.returncode:
                    raise RuntimeError(f"{name} failed: {receipt}")
                outputs = {(case, suffix): struct.unpack("<512f", (work / f"{case}{suffix}.bin").read_bytes())
                           for case in CASES for suffix in ("", "-u1")}
                if name == "native_amd":
                    reference_outputs = outputs
                    for suffix in ("", "-u1"):
                        if not any(v > 0 for v in outputs[("active", suffix)]):
                            raise ValueError(f"active probe did not write positive {suffix or 'u0'} output")
                else:
                    for key, values in outputs.items():
                        if any(not math.isclose(a, b, rel_tol=1e-6, abs_tol=1e-6)
                               for a, b in zip(reference_outputs[key], values, strict=True)):
                            raise ValueError(f"{name} differs from native wave64 for {key}")
                results[name] = {"adapter": receipt.strip(), "cases": len(CASES),
                                 "outputs": 2, "compared_words_per_output": 512}
        finally:
            os.environ.clear()
            os.environ.update(saved)
        evidence = {"scope": "Packaged global 485 probe irradiance, both output textures: portable execution versus native Radeon wave64. The reference uses the same translated shader with native wave operations and does not independently validate the rest of the translation.",
                    "source_sha256": digest(work / "native.cso"), "compiler_sha256": digest(compiler),
                    "cases": list(CASES), "tolerance": 1e-6, "runs": results}
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(json.dumps(evidence, indent=2) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
